const d=(o,r)=>{const e=o.toLowerCase().replace(/[^a-z0-9\s]/g,"").split(/\s+/).filter(Boolean),i=[];for(let s=0;s<=e.length-r;s++)i.push(e.slice(s,s+r).join(" "));return i},N=o=>o?o.split(/\n\n+/).filter(r=>r.trim().split(/\s+/).filter(Boolean).length>=10):[],y=(o,r)=>{if(!o||!r||r.length===0)return{score:0,matches:[],totalParagraphs:0};const e=N(o),i=r.filter(t=>t.keyFindings&&t.keyFindings.length>0).map(t=>({title:t.title,text:t.keyFindings.join(" ")}));if(i.length===0)return{score:0,matches:[],totalParagraphs:e.length};const s=new Map;for(const t of i){const a=d(t.text,5);for(const n of a)s.has(n)||s.set(n,[]),s.get(n).push(t.title)}const u=[];let m=0,g=0;for(const t of e){const a=t.split(/\s+/).filter(Boolean).length;g+=a;const n=d(t,5);if(n.length===0)continue;let p=0;const f={};for(const l of n){const c=s.get(l);if(c){p++;for(const h of c)f[h]=(f[h]||0)+1}}const M=Math.round(p/n.length*100);if(M>=15){const l=Object.entries(f).sort((c,h)=>h[1]-c[1])[0];u.push({paragraph:t.substring(0,150)+(t.length>150?"...":""),source:l?l[0]:"Unknown",similarity:M,wordCount:a}),m+=p}}const G=g>0?Math.round(m/Math.max(1,g/5)*100):0;return{score:Math.min(G,100),matches:u.sort((t,a)=>a.similarity-t.similarity).slice(0,10),totalParagraphs:e.length}};export{y as checkPlagiarism};
